import to from 'await-to-js';
import {
  takeEvery,
  put,
  select,
  call,
  all,
  fork,
  spawn,
  cancel,
  cancelled,
  take,
} from 'redux-saga/effects';
import { eventChannel } from 'redux-saga';

import { resolveCurrentRouteLanguage } from '~/i18n/redux/sagas';
import { selectCurrentLanguage } from '~/i18n/redux/selectors';
import {
  LIVE_ENTRY_NAVIGATE,
  LIVE_ENTRY_PREFIX,
  LIVE_ENTRY_RESET,
  LIVE_ENTRY_ROUTE_LOAD_OPTIONS,
  LIVE_ENTRY_UPDATE,
  SET_ENTRY,
  SET_ANCESTORS,
  SET_NAVIGATION_PATH,
  SET_ROUTE,
  SET_SIBLINGS,
  UPDATE_LOADING_STATE,
} from './types';
import { GET_NODE_TREE } from '~/redux/types/navigation';
import {
  selectCurrentAncestors,
  selectCurrentNode,
  selectCurrentProject,
  selectCurrentSiblings,
  selectMappedEntry,
  selectRouteEntry,
  selectRouteEntryEntryId,
  selectRouteEntryLanguage,
} from './selectors';
import { hasNavigationTree } from '~/redux/selectors/navigation';
import { selectVersionStatus } from '~/redux/selectors/version';
import { handleRequiresLoginSaga } from '~/user/redux/sagas/login';
import { ensureNodeTreeSaga } from '~/redux/sagas/navigation';

import { LoginHelper } from '~/user';
import {
  findContentTypeMapping,
  getSearchOptions,
} from '../util/find-contenttype-mapping';
import { routeEntryByFieldsQuery } from '../util/queries';
import { handleSearchSaga } from './invokeSearch';
import { reduxInjectorSaga } from '~/redux/sagas/injector';
import { routeParams } from '~/search';
import { isSSR } from '~/util/env';
import { logError } from '~/util/errors';

const error = (e, message) =>
  logError(`[routeSaga]${message ? ` ${message}` : ''}`, e);

let livePreviewTask = null;
let livePreviewNavigationTask = null;

export const routingSagas = [
  takeEvery(SET_NAVIGATION_PATH, getRouteSaga),
  takeEvery(SET_ROUTE, setRouteSaga),
];

/**
 * To navigate / push a specific route via redux middleware
 * @param {path, state} action
 */
function* setRouteSaga(action) {
  yield put({
    type: 'CALL_HISTORY_METHOD',
    payload: {
      method: 'push',
      args: [action.path, action.state],
    },
  });
}

/** Request a privileged access token from the release endpoint */
const releaseAccessToken = async releaseUri => {
  const [error, response] = await to(
    fetch(releaseUri, { method: 'POST', credentials: 'same-origin' })
  );
  if (error || !response.ok)
    return [error || new Error(`Release failed: ${response.status}`)];

  const [parseError, body] = await to(response.json());
  return parseError ? [parseError] : [undefined, body.accessToken];
};

/**
 * Ensure we hold an access token that can serve this route before any content
 * is requested. Returns false when the route must not continue.
 */
function* ensureAccessTokenSaga(action) {
  // The server never releases a token to itself so this should never be hit
  if (isSSR) return true;

  const config = window.DELIVERY_API_CONFIG || DELIVERY_API_CONFIG /* global DELIVERY_API_CONFIG */ || {};

  // If we already hold a token, or this deployment doesn't gate one
  if (config.accessToken) return true;

  // Blocking - validates the user from cookies, redirects to sign-in if it can't
  const userLoggedIn = yield call(handleRequiresLoginSaga, {
    ...action,
    requireLogin: true,
  });
  if (!userLoggedIn) return false;

  // If NO releaseUri is configured, the deployment doesn't gate a token instead
  // auth is handled by the user's own credentials (cookies) and we can continue
  if (config.releaseUri) {
    const [releaseError, accessToken] = yield call(
      releaseAccessToken,
      config.releaseUri
    );

    // Added userLoggedIn check as a logged-in user can use their credentials for Delivery API access
    if (releaseError || !accessToken || !userLoggedIn) {
      error(releaseError, 'unable to release an access token');
      // Authenticated but nothing released. Don't fall through to published
      // content - one versionStatus per host.
      // REVIEW: assumes a refusal is an authorisation problem. Revisit if the
      // endpoint can refuse for other reasons.
      LoginHelper.ClientRedirectToAccessDeniedPage(action.location?.pathname);
      return false;
    }

    // deliveryApiConfig() spreads this global on every call, so mutating it here
    // is picked up by the next request without re-plumbing anything downstream
    config.accessToken = accessToken;
    // update (mutate) the existing config in the SSRContext
    action.ssr?.config && (action.ssr.config.accessToken = accessToken);
  }
  return true;
}

function* getRouteSaga(action) {
  let entry = null;
  try {
    const {
      withEvents,
      routes: { ContentTypeMappings = {} } = {},
      staticRoute,
      // get api instance from ssr context that is connected to the specific request in ssr
      ssr: { api, subsitePath },
    } = action;

    // Live preview is scoped to the first entry route we've landed on and ends on any route change
    if (livePreviewTask) {
      yield cancel(livePreviewTask);
      livePreviewTask = null;
    }

    // Back/forward: the user navigates away from the previewed entry and drops the `?livePreview=true`
    // query string cancelling/omitting the main live preview messaging channel
    if (
      typeof window !== 'undefined' &&
      !livePreviewNavigationTask &&
      (parent !== window || opener)
    ) {
      livePreviewNavigationTask = yield spawn(watchLivePreviewNavigationSaga);
    }

    // Resolve an access token that can serve this route before we request
    // any content with it
    if (!(yield call(ensureAccessTokenSaga, action))) {
      yield put({ type: UPDATE_LOADING_STATE, isLoading: false });
      return;
    }

    // Inject redux { key, reducer, saga } provided by staticRoute
    if (staticRoute && staticRoute.route.injectRedux)
      yield call(reduxInjectorSaga, staticRoute.route.injectRedux);

    // Variables we will pass to setRouteEntry
    let pathNode = null,
      ancestors = null,
      children = [],
      siblings = null;

    let contentTypeMapping = {};

    // These variables are the return values from
    // calls to withEvents.onRouteLoad and onRouteLoaded
    let appsays,
      requireLogin = false,
      searchOptions = false;

    // Route parameters are used for driving search options and live preview functionality,
    // and are passed to the consuming app via withEvents hooks
    const params = routeParams(staticRoute, action.location);

    if (withEvents && withEvents.onRouteLoad) {
      appsays = yield withEvents.onRouteLoad(action);
    }

    // We could improve this further with a reusable mapper
    // function to return these params given a static route
    // or matching a content type mapping we could call at various points
    // enabling us to mix and match and prioritise inputs if there are multiple
    let linkDepth = staticRoute?.route?.fetchNode?.linkDepth;
    let fields = staticRoute?.route?.fetchNode?.fields;
    let fieldLinkDepths = staticRoute?.route?.fetchNode?.fieldLinkDepths;
    let entryMapper = staticRoute?.route?.fetchNode?.entryMapper;

    // TODO: drop this default fallback to 0 with CRBv5 as 2 is a legacy arbritary medium and encourages
    // routing optimisation to be ignored resulting in excessive API calls going unnoticed
    // Use of `linkDepth` should be avoided in favour of `fieldLinkDepths` with newer Contensis versions
    const defaultLinkDepth =
      appsays?.entryLinkDepth !== undefined ? appsays.entryLinkDepth : 2;
    const defaultFieldLinkDepths = appsays?.entryFieldLinkDepths;

    const setStaticRouteLimits =
      typeof linkDepth !== 'undefined' || fields || fieldLinkDepths;

    const setContentTypeLimits = !!ContentTypeMappings.find(
      ct => ct.fields || ct.linkDepth || ct.nodeOptions || ct.fieldLinkDepths
    );

    // Limits set in a static route take priority over limits in a content type mapping
    // If we have limits set in:
    //   - a matched static route - set them here to resolve everything with the initial node upfront
    //   - any content type mapping - we set defaults for the initial node resolve then
    //     - identify the contentTypeId and locate the content type mapping
    //     - perform a second search query with the limits applied from the content type mapping
    // If no limits are set in route configuration:
    //   - fall back to entryLinkDepth and entryFieldLinkDepths provided by the app in `onRouteLoad` event
    //   - or default to entryLinkDepth of 2 with all fields (default for legacy `/preview` endpoints)
    fields = setStaticRouteLimits
      ? fields || '*'
      : setContentTypeLimits
        ? ['sys.contentTypeId', 'sys.id']
        : '*';
    linkDepth =
      setStaticRouteLimits && typeof linkDepth !== 'undefined'
        ? linkDepth
        : setContentTypeLimits
          ? 0
          : defaultLinkDepth;
    fieldLinkDepths = setStaticRouteLimits
      ? fieldLinkDepths
      : setContentTypeLimits
        ? undefined
        : defaultFieldLinkDepths;

    const state = yield select();
    const routeEntry = selectRouteEntry(state, 'js');
    const routeNode = selectCurrentNode(state, 'js');
    const currentPath = action.path; //selectCurrentPath(state);
    const contentPath = action.contentPath;
    const deliveryApiStatus = selectVersionStatus(state);
    const project = selectCurrentProject(state);
    // const isHome = currentPath === '/';
    const isPreview = currentPath && currentPath.startsWith('/preview/');
    const currentLanguage = selectCurrentLanguage(state);
    const defaultLang =
      (appsays && appsays.defaultLang) || currentLanguage || 'en-GB';

    if (
      !isPreview &&
      (appsays?.customRouting ||
        (staticRoute && !staticRoute.route.fetchNode) ||
        (routeEntry &&
          action.statePath === action.path &&
          appsays?.refetchNode !== true))
    ) {
      // To prevent erroneous 404s and wasted network calls, this covers
      // - appsays customRouting and does SET_ENTRY etc. via the consuming app
      // - all staticRoutes (where custom 'route.fetchNode' attribute is falsey)
      // - standard Contensis SiteView Routing where we already have that entry in state
      if (routeEntry && (!staticRoute || staticRoute?.route?.fetchNode)) {
        pathNode = { ...routeNode, entry: null };
        pathNode.entry = entry = routeEntry;

        yield put({
          type: UPDATE_LOADING_STATE,
          isLoading: false,
        });
        if (params.livePreview && typeof window !== 'undefined') {
          // Update the "limits" (fields, fieldLinkDepths and linkDepth)
          // used in route resolution (likely SSR) based on the entry's content type mapping
          // so that we can pass the correct limits to live preview parent
          contentTypeMapping = findContentTypeMapping(
            ContentTypeMappings,
            entry.sys.contentTypeId
          );
          // Static route limits override content type mapping limits
          fields = setStaticRouteLimits
            ? fields || '*'
            : contentTypeMapping?.fields || '*';
          linkDepth = setStaticRouteLimits
            ? linkDepth || 0
            : typeof contentTypeMapping?.linkDepth !== 'undefined'
              ? contentTypeMapping.linkDepth
              : defaultLinkDepth;
          fieldLinkDepths = setStaticRouteLimits
            ? fieldLinkDepths
            : contentTypeMapping?.fieldLinkDepths || fieldLinkDepths;
        }
      } else
        yield call(
          setRouteEntry,
          currentPath,
          routeEntry,
          yield select(selectCurrentNode),
          yield select(selectCurrentAncestors),
          yield select(selectCurrentSiblings)
        );
    } else {
      // Handle preview routes (legacy - can we remove?)
      if (isPreview) {
        let splitPath = currentPath.split('/');
        let entryGuid = splitPath[2];
        let language = defaultLang;
        if (splitPath.length >= 3) {
          //set lang key if available in the path, else use default lang
          //assumes preview url on content type is: http://preview.ALIAS.contensis.cloud/preview/{GUID}/{LANG}
          if (splitPath.length == 4) language = splitPath[3];
          // According to product dev we cannot use Node API
          // for previewing entries as it gives a response of []
          // -- apparently it is not correct to request latest content
          // with Node API
          let previewEntry = yield api
            .getClient(deliveryApiStatus, project)
            .entries.get({
              id: entryGuid,
              language,
              linkDepth: defaultLinkDepth,
            });
          if (previewEntry) {
            pathNode = { entry: previewEntry };
            ({ entry } = pathNode || {});
          }
        }
      } else {
        // Handle all other routes
        let nodeError = undefined;
        // Resolve a stub of route node if we are setting limits in content type mappings
        // Resolve the complete entry with the node if we are setting limits in a static route
        [nodeError, pathNode] = yield to(
          api.getNode(
            {
              depth: 0,
              path: contentPath,
              entryFields: fields,
              entryLinkDepth: linkDepth,
              entryFieldLinkDepths: fieldLinkDepths,
              // language parameter is not used when resolving a node by path
              // https://www.contensis.com/help-and-docs/apis/delivery-http/navigation/nodes/get-a-node-by-path
              // language: defaultLang,
              versionStatus: deliveryApiStatus,
            },
            project
          )
        );
        if (nodeError) {
          if ([401, 403].includes(nodeError.status)) {
            // Capture specific auth errors with the delivery api
            // and fire the user down the handleRequiresLoginSaga
            // If auth was successful via a refreshToken we need to reload the page
            // to run this getRouteSaga again with the security token cookie
            const userLoggedIn = yield call(handleRequiresLoginSaga, {
              ...action,
              requireLogin: true,
            });
            if (userLoggedIn && nodeError.status === 401) {
              // Reload the route so we can re-run the routing request now the
              // authentication cookies are written
              return yield call(setRouteSaga, { path: currentPath });
            } else if (userLoggedIn && nodeError.status === 403) {
              const accessDeniedRoute =
                LoginHelper.GetAccessDeniedRoute(currentPath);
              // So we don't get stuck in a loop if the user is already on the access denied page
              if (currentPath !== accessDeniedRoute) {
                return yield call(setRouteSaga, {
                  path: LoginHelper.GetAccessDeniedRoute(currentPath),
                });
              } else {
                return yield call(do500, nodeError);
              }
            } else {
              return yield call(do500, nodeError);
            }
          } else throw nodeError;
        } else ({ entry } = pathNode || {});

        // Try resolve a content type mapping
        if (pathNode?.entry?.sys?.id && pathNode.entry.sys.contentTypeId) {
          // Get fields[] and linkDepth from ContentTypeMapping to get the entry data
          // and current node's ordinates at a specified depth with specified fields
          contentTypeMapping = findContentTypeMapping(
            ContentTypeMappings,
            pathNode.entry.sys.contentTypeId
          );
        }

        // Run a second search query if we aren't setting limits from a static route
        // but we are setting limits from a content type mapping, now we have a handle
        // on a contentTypeId from the resolve node, we can apply the right limits when
        // fetching the entry
        if (
          !setStaticRouteLimits &&
          setContentTypeLimits &&
          pathNode?.entry?.sys?.id
        ) {
          // Now we have a handle on a content type mapping we can
          // reassign the query limiting variables if we haven't
          // already set them in a static route
          if (!setStaticRouteLimits)
            ({
              fieldLinkDepths,
              fields,
              linkDepth = defaultLinkDepth,
            } = contentTypeMapping || {});

          const query = routeEntryByFieldsQuery(
            pathNode.entry.sys.id,
            pathNode.entry.sys.language,
            pathNode.entry.sys.contentTypeId,
            fields,
            fieldLinkDepths,
            deliveryApiStatus
          );
          const payload = yield api.search(query, linkDepth, project);
          if (payload?.items?.length > 0) {
            pathNode.entry = entry = payload.items[0];
          }
        }
      }

      // make calls to fetch node ancestors, children,
      // siblings or entire node tree
      [ancestors, children, siblings] = yield call(
        resolveCurrentNodeOrdinates,
        {
          api,
          appsays,
          contentTypeMapping:
            contentTypeMapping || staticRoute?.route?.fetchNode || {},
          language: defaultLang,
          path: contentPath,
          pathNode,
          project,
          subsitePath,
          versionStatus: deliveryApiStatus,
        }
      );

      if (children) pathNode.children = children;
    }

    // We initially listened for SET_ENTRY to complete before
    // resolving the current route language, but this meant
    // that the language change was not captured in time for the SSR response
    yield call(resolveCurrentRouteLanguage, {
      entry: pathNode?.entry,
      node: pathNode,
    });

    const contentTypeRoute = findContentTypeMapping(
      ContentTypeMappings,
      pathNode?.entry?.sys?.contentTypeId
    );

    // Inject redux { key, reducer, saga } provided by ContentTypeMapping
    if (contentTypeRoute?.injectRedux)
      yield call(reduxInjectorSaga, contentTypeRoute.injectRedux);

    // Have we defined search options in the route configuration (for triggering search)
    const routeSearchOptions = getSearchOptions(staticRoute, contentTypeRoute);

    if (withEvents && withEvents.onRouteLoaded) {
      // Check if the app has provided a requireLogin boolean flag or groups array
      // in addition to checking if requireLogin is set in the route definition
      // The app can provide an object to invoke the search saga
      ({ requireLogin, searchOptions } =
        (yield withEvents.onRouteLoaded({
          ...action,
          contentTypeRoute,
          entry,
          params,
          searchOptions: routeSearchOptions,
        })) || {});
    }

    if (requireLogin !== false) {
      // Do not call the login feature saga if requireLogin is false
      yield call(handleRequiresLoginSaga, { ...action, entry, requireLogin });
    }

    if (searchOptions || routeSearchOptions)
      yield call(handleSearchSaga, {
        ...action,
        params,
        routeSearchOptions,
        searchOptions,
      });

    if (!appsays || !appsays.preventScrollTop) {
      // Scroll into View
      if (typeof window !== 'undefined') window.scrollTo(0, 0);
    }

    if (pathNode?.entry?.sys?.id) {
      entryMapper = entryMapper || contentTypeRoute?.entryMapper;

      // A previous live preview message channel would be cancelled at the top of this saga
      if (params.livePreview && typeof window !== 'undefined') {
        livePreviewTask = yield fork(watchLivePreviewSaga, {
          currentPath,
          entry,
          entryMapper,
          pathNode,
          limits: { fields, fieldLinkDepths, linkDepth },
        });
      }

      entry = pathNode.entry;

      yield call(
        setRouteEntry,
        currentPath,
        entry,
        pathNode,
        ancestors,
        siblings,
        entryMapper,
        false,
        appsays?.refetchNode
      );
    } else {
      if (staticRoute)
        yield call(
          setRouteEntry,
          currentPath,
          null,
          pathNode,
          ancestors,
          siblings
        );
      else yield call(do404);
    }
  } catch (e) {
    error(e);
    yield call(do500, e);
  }
}

function createLivePreviewChannel() {
  return eventChannel(emit => {
    const handler = e => {
      // console.log('Received message in live preview channel', e.data);
      // NAVIGATE excluded - watchLivePreviewNavigationSaga is also listening separately
      if (
        e.data?.type?.startsWith(LIVE_ENTRY_PREFIX) &&
        e.data.type !== LIVE_ENTRY_NAVIGATE
      )
        emit(e.data);
    };
    window.addEventListener('message', handler);
    return () => window.removeEventListener('message', handler);
  });
}

/**
 * Handles back/forward for the life of the session, outside the `?livePreview=true` route gate.
 * Provides history back and forward only so safe to run on any route.
 */
function* watchLivePreviewNavigationSaga() {
  const channel = eventChannel(emit => {
    const handler = e => {
      if (e.data?.type === LIVE_ENTRY_NAVIGATE) emit(e.data);
    };
    window.addEventListener('message', handler);
    return () => window.removeEventListener('message', handler);
  });
  try {
    while (true) {
      const { payload: direction } = yield take(channel);
      if (direction === 'back') history.back();
      else if (direction === 'forward') history.forward();
    }
  } finally {
    if (yield cancelled()) channel.close();
  }
}

function* watchLivePreviewSaga(context) {
  const channel = createLivePreviewChannel();
  const routeLoadOptions = {
    type: LIVE_ENTRY_ROUTE_LOAD_OPTIONS,
    payload: context.limits,
  };
  if (routeParams().debug) routeLoadOptions.debug = context.pathNode;
  // When not in an iframe, parent will be the same as window, as this is the "top-level"
  // we can post the message to the opener window instead
  (parent !== window ? parent : opener)?.postMessage(routeLoadOptions, '*');

  try {
    while (true) {
      const data = yield take(channel);
      let entry = yield select(selectRouteEntry);
      if (data.type === LIVE_ENTRY_RESET) {
        console.log('Resetting live preview entry to original route entry');
        entry = context.entry;
      } else if (data.type === LIVE_ENTRY_UPDATE) {
        console.log('Handling live preview update', data);
        entry = { ...entry, ...data.payload };
      }
      yield call(
        setRouteEntry,
        context.currentPath,
        entry,
        context.pathNode,
        null, // ancestors unchanged
        null, // siblings unchanged
        context.entryMapper,
        false,
        true // we need to remap the entry here
      );
    }
  } finally {
    if (yield cancelled()) channel.close();
  }
}

function* resolveCurrentNodeOrdinates(action) {
  const {
    api,
    appsays,
    contentTypeMapping,
    language,
    path,
    pathNode,
    project,
    subsitePath,
    versionStatus,
  } = action;
  const apiCall = [() => null, () => null, () => null, () => null];

  // if appsays customNavigation: true, we will set doNavigation to false
  // if appsays customNavigation: { ... }, we will set doNavigation to the customNavigation object and check for child elements
  // if appsays nothing we will set doNavigation to true and continue to do navigation calls
  const doNavigation =
    !appsays ||
    (appsays?.customNavigation === true
      ? false
      : appsays?.customNavigation || true);

  const {
    entryLinkDepth = 0,
    fieldLinkDepths,
    fields,
    linkDepth,
    nodeOptions = {},
  } = contentTypeMapping;

  if (pathNode && pathNode.id) {
    if (doNavigation === true || doNavigation.ancestors) {
      apiCall[0] = function* getAncestors() {
        try {
          return yield api.getAncestors(
            {
              id: pathNode.id,
              language,
              versionStatus,
              startLevel: (subsitePath || '').split('/').length,
            },
            project
          );
        } catch (ex) {
          error(ex, 'Problem fetching ancestors');
          return [];
        }
      };
    }

    const childrenDepth =
      doNavigation === true || doNavigation.children === true
        ? 1
        : (doNavigation && doNavigation.children) || 0;

    if (
      (typeof nodeOptions?.children === 'undefined' && childrenDepth > 0) ||
      nodeOptions.children
    ) {
      const childrenOptions =
        !nodeOptions.children || typeof nodeOptions.children === 'boolean'
          ? {}
          : nodeOptions.children;
      apiCall[1] = function* getChildren() {
        try {
          return yield api.getNode(
            {
              depth:
                childrenOptions.depth !== undefined
                  ? childrenOptions.depth
                  : childrenDepth,
              path,
              entryFieldLinkDepths:
                childrenOptions.fieldLinkDepths || fieldLinkDepths,
              entryFields: childrenOptions.fields || fields || undefined,
              entryLinkDepth:
                typeof childrenOptions.linkDepth !== 'undefined'
                  ? childrenOptions.linkDepth
                  : typeof linkDepth !== 'undefined'
                    ? linkDepth
                    : entryLinkDepth,
              language,
              versionStatus,
            },
            project
          );
        } catch (ex) {
          error(ex, 'Problem fetching children');
          return [];
        }
      };
    }

    if (
      (typeof nodeOptions?.siblings === 'undefined' && doNavigation.siblings) ||
      nodeOptions.siblings
    ) {
      apiCall[2] = function* getSiblings() {
        try {
          return yield api.getSiblings(
            {
              id: pathNode.id,
              entryFieldLinkDepths:
                nodeOptions?.siblings?.fieldLinkDepths || fieldLinkDepths,
              entryFields: nodeOptions?.siblings?.fields || fields || undefined,
              entryLinkDepth:
                typeof nodeOptions?.siblings?.linkDepth !== 'undefined'
                  ? nodeOptions.siblings.linkDepth
                  : typeof linkDepth !== 'undefined'
                    ? linkDepth
                    : entryLinkDepth,
              includeInMenu: true,
              language,
              versionStatus,
            },
            project
          );
        } catch (ex) {
          error(ex, 'Problem fetching siblings');
          return [];
        }
      };
    }
  }

  const isTreeLoaded = yield select(hasNavigationTree);
  if (!isTreeLoaded && (doNavigation === true || doNavigation.tree))
    apiCall[3] = function* getNodeTree() {
      const treeDepth =
        doNavigation === true ||
          !doNavigation.tree ||
          doNavigation.tree === true
          ? 2
          : doNavigation.tree;

      if (typeof window !== 'undefined') {
        return yield put({
          type: GET_NODE_TREE,
          ...action,
          treeDepth,
        });
      } else {
        return yield call(ensureNodeTreeSaga, { ...action, treeDepth });
      }
    };

  const [loadAncestors, loadChildren, loadSiblings, loadTree] = apiCall;
  const [ancestors, nodeWithChildren, siblings] = yield all([
    loadAncestors(),
    loadChildren(),
    loadSiblings(),
    loadTree(),
  ]);
  return [ancestors, nodeWithChildren?.children, siblings];
}

function* setRouteEntry(
  currentPath,
  entry,
  node,
  ancestors,
  siblings,
  entryMapper,
  notFound = false,
  remapEntry = false
) {
  const entrySys = (entry && entry.sys) || {};

  // Update a window global to provide the preview toolbar
  // an updated entry id in client-side navigation
  if (typeof window !== 'undefined') window.ContensisEntryId = entrySys.id;

  const currentEntryId = yield select(selectRouteEntryEntryId);
  const currentEntryLang = yield select(selectRouteEntryLanguage);
  const mappedEntry = !entryMapper
    ? null
    : currentEntryId === entrySys.id &&
      currentEntryLang === entrySys.language &&
      remapEntry === false
      ? (yield select(selectMappedEntry, 'js')) || {}
      : yield mapRouteEntry(entryMapper, {
        ...node,
        entry,
        ancestors,
        siblings,
      });

  yield all([
    put({
      type: SET_ENTRY,
      id: entrySys.id,
      currentPath,
      entry,
      mappedEntry,
      node,
      notFound,
    }),
    ancestors &&
    put({
      type: SET_ANCESTORS,
      ancestors,
    }),
    siblings &&
    put({
      type: SET_SIBLINGS,
      siblings,
    }),
  ]);
}

function* mapRouteEntry(entryMapper, node) {
  try {
    if (typeof entryMapper === 'function') {
      const state = yield select();
      const mappedEntry = yield call(entryMapper, node, state);
      return mappedEntry;
    }
  } catch (e) {
    error(e, 'Error in entryMapper:');
    throw e;
  }
  return;
}

function* do404() {
  yield call(clientReloadHitServer);
  yield put({
    type: SET_ENTRY,
    id: null,
    entry: null,
    notFound: true,
  });
}

function* clientReloadHitServer() {
  const stateEntry = yield select(selectRouteEntry);

  // If in client and there is a stateEntry.sys field reload the page,
  // on the 2nd load stateEntry.sys should be null at this point,
  // we do not wish to reload again and get stuck in an infinite reloading loop
  if (typeof window !== 'undefined' && (stateEntry?.sys || null)) {
    window.location.reload();
  }
}

function* do500(error) {
  yield put({
    type: SET_ENTRY,
    id: null,
    entry: null,
    notFound: true,
    isError: true,
    error,
    statusCode: error && error.status ? error.status : 500,
  });
}
